 * @exception
 * @example
 */
scwin.fn_com_isur_nm = function (keyCode, info) {

	var cnt = 0;
	////var len=scwin.js_com_Isurcd.value.length;
	////var txtVal=scwin.js_com_Isurcd.value.toUpperCase();
	var len = $p.getComponentById("txb_isur_cd").getValue().length;
	var txtVal = $p.getComponentById("txb_isur_cd").getValue().toUpperCase();
	////Grd_com_isur.Redraw ="false";
	if (len > 0) {
		foColum = (isNaN(txtVal) ? 1 : 2);
	}
	if (foColum == 1) {
		skw = txtVal;
		if (keyCode == 13) {
			scwin.jongmokNameSearch();
		}
		/*
						MxDataSet_com_isur.SortExpr="+COM_ABBRV";
						MxDataSet_com_isur.Sort();
						for(i=1; i<=MxDataSet_com_isur.countrow; i++){
							var name = MxDataSet_com_isur.NameValue(i,"COM_ABBRV").substring(0,len).toUpperCase();
							if (txtVal <= name){
								cnt=i;
								break;
							}
						}
		*/
	} else {
		if (keyCode == 13) {
			scwin.fn_com_Confirm_set();
		} else {
			////Grd_com_isur.style.display = "";
			skw = "";
			MxDataSet_com_isur.Filter();
			MxDataSet_com_isur.SortExpr = "+ISUR_CD";
			MxDataSet_com_isur.Sort();
			for (i = 1; i <= MxDataSet_com_isur.countrow; i++) {
				var name = MxDataSet_com_isur.NameValue(i, "ISUR_CD").substring(0, len).toUpperCase();
				if (txtVal <= name) {
					cnt = i;
					break;
				}
			}
		}
	}
	////Grd_com_isur.Redraw ="true";
	////MxDataSet_com_isur.Rowposition = cnt+11; 
	////MxDataSet_com_isur.Rowposition = cnt;
};

//Ajax 사용하기 위한 함수(2009.11.20 P.H.J)
/**
 * @method
 * @name xmlDocLoad
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.xmlDocLoad = function (strXml) {
	xmlDoc = new ActiveXObject("Microsoft.XMLDOM");
	xmlDoc.async = false;

	if (!xmlDoc.loadXML(strXml)) {
		alert("error:" + xmlDoc.parseError.reason);
		//gSetXMLDataSync = false;
		xmlDoc = "";
		return "";
	}
	return xmlDoc;
};

