/**
 * @method
 * @name ins_popupOpen
 * @description 팝업호출 공통 — grdObj: 대상 값 받아올 CD, grdObj2: 대상 값 받아올 VALUE,
 *              strUrl: 대상팝업 경로(풀), strTitle: 대상팝업 제목, strW/strH: 팝업 가로/세로 길이
 *              사용례: ins_popupOpen(txb_cd, txb_nm, url, title, w, h);  (CD 또는 VALUE 는 "" 생략 가능)
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.ins_popupOpen = function (grdObj, grdObj2, strUrl, strTitle, strW, strH) {
	scwin.js_ins_popup_cd = grdObj;//cd
	scwin.js_ins_popup_nm = grdObj2;//nm

	strW = parseInt(strW) + 10;
	strH = parseInt(strH) + 10;

	// 팝업 오픈
	const url = "/ui/ins/common/" + strUrl + ".xml";
	const param = {};

	const options = {
		id: "ins_popup",
		popupName: strTitle,
		frameModal: "top",
		width: strW,
		height: strH,
	};

	$c.win.openPopup(url, options, param);
};

