		url += "&CD_ID_FLAG=A";

		//alert(url);

		dtsObj.DataID = url;
		dtsObj.Reset();
	*/
	dtsObj.setData(["03478", "1", "1 ELS", "03478", "3", "3 ELB", "03478", "2", "2 DLS", "03478", "4", "4 DLB"]);
};

/**
 * @method
 * @name ins_combo_set2
 * @description 
 *              dtsObj : 콤보 Object
 *              vScrenID: 화면ID
 *              SCREN_PROCS_TP_CD : 조회 01
 *              cdId : 공통 코드 ID (조회대상)
 *              flag : 디폴트 구분
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.ins_combo_set2 = function (dtsObj, vScrenID, SCREN_PROCS_TP_CD, cdId, flag, del_cd) {

	var method = "";
	if (flag == "ALL") {
		method = "listCodeValueNameAll"; // defaul 전체
	} else if (flag == "SEL") {
		method = "listCodeValueNameSelect"; // defaul 빈칸 
	} else if (flag == "CPBO") {
		method = "listCodeValueNameCPBO"; // CPBO 신용등급
	} else {
		method = "listCodeValueNameM"; // defaul 없음  
	}
	var url = "/CodeAction.do?method=" + method;
	url += "&SCREN_ID=" + vScrenID;
	url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD;
	url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
	url += "&CD_ID_M=" + cdId;
	url += "&CD_ID_FLAG=A";

	//alert(url);
	dtsObj.SyncLoad = "true";
	dtsObj.DataID = url;
	dtsObj.Reset();

	dtsObj.DeleteRow(del_cd);
	//dtsObj.DeleteRow(2);
	//alert(del_cd);
	//alert(dtsObj.RowPosition);
	//dtsObj.InsertRow(dtsObj.RowPosition);
	//fn_ResetCdValue(dtsObj);
};

