/**
 * @method
 * @name fn_alertRequiredDelByWeb
 * @description 
 *              팝업호출 공통
 *              신청자 삭제 건 알림 공통
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_alertRequiredDelByWeb = async function () {
	var msg = "[ 신청자 삭제 요청건 ]";
	msg = msg + "\n - 본 코드는 신청자로부터(isin.krx.co.kr) 삭제요청이 들어온 상태입니다.";
	msg = msg + "\n - 신청자요청 종목을 삭제하려면,[ 유가증권관리 > 표준코드삭제요청조회및승인 ]화면에서 삭제해야 합니다.";
	msg = msg + "\n ▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒";
	msg = msg + "\n                        <  해당화면( 표준코드삭제요청조회및승인 )으로 이동하시겠습니까?  > ";
	msg = msg + "\n ▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒ ";

	var rtn = await $c.win.confirm(msg);
	if (rtn == true) { // [확인] 버튼이 눌려졌을 경우
		// 팝업 오픈
		const url = "/ui/rcpt/ULDINS11000.xml";
		const param = {};

		const options = {
			id: "ULDINS11000",
			popupName: "표준코드 삭제 승인_ULDINS11000",
			frameModal: "top",
			width: 1300,
			height: 780,
		};

		await $c.win.openPopup(url, options, param);			
	}
};

