/**
 * @method
 * @name ins_clearPwd
 * @description 비밀번호 초기화
 *              dtsObj : 콤보 Object
 *              vScrenID: 화면ID
 *              SCREN_PROCS_TP_CD : 조회 01
 *              FLAG : 발행기관, 표준코드 구분  0 : 발행기관  1: 표준코드
 *              KEY : 표준코드 신청번호 또는 발행기관 신청번호
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.ins_clearPwd = function (dtsObj, vScrenID, SCREN_PROCS_TP_CD, FLAG, KEY, SVC_RUN_YN) {

	if (SVC_RUN_YN == "N") {
		$c.win.alert("메일서버에 장애가 발생하였습니다.\n시스템 관리자에게 문의 하시기 바랍니다.");
		return;
	}

	if (KEY == "") { $c.win.alert("신청번호가 없습니다."); return; }
	if (txb_ENCRYP_APCT_EMAIL.value == "") { $c.win.alert("신청인 메일 정보가 없습니다."); return; }

	if (fn_CheckEmail(txb_ENCRYP_APCT_EMAIL.value) == false) return;

