/**
 * 발행년코드
 * 2005년을 5으로 기준하여... 2034년  W로 하여(5 ~4, A~W )까지...순차적 ( 알파벳 I,O,U  는제외)
 * 30년을 주기로 반복한다.
 *
 * @param yyyy
 * @return
 */
/**
 * @method
 * @name get_YYYY_Cd_for_elw
 * @description ins
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.get_YYYY_Cd_for_elw = function (yyyy) {
	var i_yyyy = 0;
	var yyyy_cd = new Array("5", "6", "7", "8", "9", "0", "1", "2", "3", "4",
		"A", "B", "C", "D", "E", "F", "G", "H", "J", "K",
		"L", "M", "N", "P", "Q", "R", "S", "T", "V", "W");
	i_yyyy = (parseInt(yyyy) - 2005) % 30;

	return yyyy_cd[i_yyyy];
};

